INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > MongoDB > CRUD-Operationen
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann die insertOne-Operation in MongoDB genau ein Dokument in eine Collection einfügen?', 2, '[{"text": "Ja", "correct": true, "because": "insertOne fügt ein einzelnes Dokument ein"}, {"text": "Nein", "correct": false, "because": "Definition von insertOne"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist findOne in MongoDB dazu geeignet, mehrere Dokumente gleichzeitig zurückzugeben?', 2, '[{"text": "Nein", "correct": true, "because": "findOne gibt nur ein Dokument zurück"}, {"text": "Ja", "correct": false, "because": "Nur ein Ergebnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Können updateMany-Operationen mehrere Dokumente in einer Collection basierend auf einer Bedingung ändern?', 2, '[{"text": "Ja", "correct": true, "because": "updateMany ändert mehrere passende Dokumente"}, {"text": "Nein", "correct": false, "because": "Zweck von updateMany"}]'),
('00000000-0000-0000-0000-000000000000', 'Löscht deleteOne in MongoDB immer alle Dokumente einer Collection?', 2, '[{"text": "Nein", "correct": true, "because": "deleteOne löscht nur ein Dokument"}, {"text": "Ja", "correct": false, "because": "Nur ein Dokument betroffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann insertMany in MongoDB mehrere Dokumente in einer einzigen Operation einfügen?', 2, '[{"text": "Ja", "correct": true, "because": "insertMany fügt mehrere Dokumente hinzu"}, {"text": "Nein", "correct": false, "because": "Definition von insertMany"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche MongoDB-Operation fügt ein einzelnes Dokument in eine Collection ein?', 2, '[{"text": "insertOne", "correct": true, "because": "Fügt ein Dokument ein"}, {"text": "insertMany", "correct": false, "because": "Fügt mehrere ein"}, {"text": "findOne", "correct": false, "because": "Abrufen, nicht einfügen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operation in MongoDB gibt das erste passende Dokument aus einer Collection zurück?', 3, '[{"text": "findOne", "correct": true, "because": "Gibt ein Dokument zurück"}, {"text": "find", "correct": false, "because": "Gibt mehrere zurück"}, {"text": "updateOne", "correct": false, "because": "Ändert, nicht abruft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche MongoDB-Operation ändert mehrere Dokumente basierend auf einer Bedingung?', 2, '[{"text": "updateMany", "correct": true, "because": "Ändert mehrere Dokumente"}, {"text": "updateOne", "correct": false, "because": "Ändert nur eines"}, {"text": "deleteMany", "correct": false, "because": "Löscht, nicht ändert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operation entfernt genau ein Dokument aus einer MongoDB-Collection?', 2, '[{"text": "deleteOne", "correct": true, "because": "Löscht ein Dokument"}, {"text": "deleteMany", "correct": false, "because": "Löscht mehrere"}, {"text": "findOne", "correct": false, "because": "Abrufen, nicht löschen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operation fügt mehrere Dokumente gleichzeitig in eine Collection ein?', 2, '[{"text": "insertMany", "correct": true, "because": "Fügt mehrere Dokumente ein"}, {"text": "insertOne", "correct": false, "because": "Nur ein Dokument"}, {"text": "updateMany", "correct": false, "because": "Ändert, nicht einfügt"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche CRUD-Operationen gibt es in MongoDB?', 4, '[{"text": "insertOne", "correct": true, "because": "Einfügen eines Dokuments"}, {"text": "find", "correct": true, "because": "Abrufen mehrerer Dokumente"}, {"text": "updateMany", "correct": true, "because": "Ändern mehrerer Dokumente"}, {"text": "createTable", "correct": false, "because": "SQL, nicht MongoDB"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat die find-Operation in MongoDB?', 3, '[{"text": "Gibt mehrere Dokumente zurück", "correct": true, "because": "Abruf aller Treffer"}, {"text": "Kann mit Filtern genutzt werden", "correct": true, "because": "Bedingungen möglich"}, {"text": "Kann sortiert werden", "correct": true, "because": "Sortierung unterstützt"}, {"text": "Ändert Dokumente", "correct": false, "because": "Nur Abruf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operationen können mehrere Dokumente in MongoDB beeinflussen?', 4, '[{"text": "insertMany", "correct": true, "because": "Fügt mehrere ein"}, {"text": "updateMany", "correct": true, "because": "Ändert mehrere"}, {"text": "deleteMany", "correct": true, "because": "Löscht mehrere"}, {"text": "findOne", "correct": false, "because": "Nur ein Dokument"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Parameter sind bei updateOne in MongoDB wichtig?', 3, '[{"text": "Filter", "correct": true, "because": "Bestimmt zu änderndes Dokument"}, {"text": "Update", "correct": true, "because": "Definiert Änderungen"}, {"text": "upsert", "correct": true, "because": "Optional, fügt bei Nichtvorhandensein ein"}, {"text": "sort", "correct": false, "because": "Für find, nicht update"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operationen unterstützen das Abrufen von Daten in MongoDB?', 3, '[{"text": "find", "correct": true, "because": "Ruft mehrere Dokumente ab"}, {"text": "findOne", "correct": true, "because": "Ruft ein Dokument ab"}, {"text": "findAndModify", "correct": true, "because": "Abruf mit Änderung"}, {"text": "deleteOne", "correct": false, "because": "Löscht, nicht abruft"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) insertOne fügt ein Dokument ein. b) Es kann mehrere Dokumente gleichzeitig einfügen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ein Dokument ja, mehrere nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) find gibt mehrere Dokumente zurück. b) findOne ändert Dokumente in der Collection.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mehrere ja, Ändern nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) updateMany kann mehrere Dokumente ändern. b) deleteOne löscht mehrere Dokumente.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mehrere ändern ja, löschen nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) insertMany fügt mehrere Dokumente ein. b) updateOne löscht Dokumente.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mehrere einfügen ja, löschen nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) deleteMany löscht mehrere Dokumente basierend auf Bedingungen. b) find kann nur ein Dokument abrufen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mehrere löschen ja, find mehrere"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

